Literal.Value:
'{
  "params": [
    {
      "name": "title",
      "value": ""
    },
    {
      "name": "subtitle",
      "value": ""
    },
    {
      "name": "currentBarColor",
      "expr": "pbiColor(1)"
    },
    {
      "name": "currentBarStroke",
      "expr": "pbiColor(1, -0.3)"
    },
    {
      "name": "totalBarColor",
      "value": "#E1E1E1"
    },
    {
      "name": "totalBarStroke",
      "value": "#A6A6A6"
    },
    {
      "name": "barStrokeWidth",
      "value": 1
    },
    {
      "name": "lollipopStemColor",
      "expr": "currentBarColor"
    },
    {
      "name": "lollipopHeadColor",
      "expr": "pbiColor(1, 0.8)"
    },
    {
      "name": "lollipopHeadStroke",
      "expr": "pbiColor(1, 0.3)"
    },
    {
      "name": "lollipopHeadStrokeWidth",
      "value": 1.5
    },
    {
      "name": "textColor",
      "value": "#252423"
    },
    {
      "name": "currentLabelColor",
      "value": "#FFFFFF"
    },
    {
      "name": "subtitleColor",
      "value": "#605E5C"
    },
    {
      "name": "valueFormat",
      "value": "$,.1f"
    },
    {
      "name": "valueDivisor",
      "value": 1000
    },
    {
      "name": "valueSuffix",
      "value": "K"
    },
    {
      "name": "shareFormat",
      "value": ".1%"
    },
    {
      "name": "tooltipValueFormat",
      "value": "$,.0f"
    },
    {
      "name": "sortBy",
      "value": "current"
    },
    {
      "name": "sortDescending",
      "value": true
    },
    {
      "name": "titleFontSize",
      "value": 12
    },
    {
      "name": "subtitleFontSize",
      "value": 9
    },
    {
      "name": "categoryFontSize",
      "value": 10
    },
    {
      "name": "categoryWrapChars",
      "value": 10
    },
    {
      "name": "categoryLabelLimit",
      "value": 140
    },
    {
      "name": "categoryGap",
      "value": 10
    },
    {
      "name": "labelFontSize",
      "value": 9
    },
    {
      "name": "shareFontSize",
      "value": 9.5
    },
    {
      "name": "labelGap",
      "value": 4
    },
    {
      "name": "labelCharWidth",
      "value": 0.55
    },
    {
      "name": "totalBarHeight",
      "value": 0.44
    },
    {
      "name": "totalBarOffset",
      "value": -0.08
    },
    {
      "name": "currentBarHeight",
      "value": 0.34
    },
    {
      "name": "currentBarOffset",
      "value": 0.13
    },
    {
      "name": "lollipopGap",
      "value": 0.07
    },
    {
      "name": "lollipopLength",
      "value": 0.18
    },
    {
      "name": "lollipopOffset",
      "value": 0
    },
    {
      "name": "lollipopStemWidth",
      "value": 2
    },
    {
      "name": "lollipopHeadSize",
      "value": 50
    },
    {
      "name": "shareAxisMax",
      "value": 0
    }
  ],
  "title": {
    "text": {
      "expr": "title"
    },
    "subtitle": {
      "expr": "subtitle"
    },
    "anchor": "start",
    "frame": "bounds",
    "offset": {
      "expr": "length(title) + length(subtitle) > 0 ? 8 : 0"
    },
    "subtitlePadding": {
      "expr": "length(title) > 0 && length(subtitle) > 0 ? 3 : 0"
    },
    "fontSize": {
      "expr": "length(title) > 0 ? titleFontSize : 0"
    },
    "fontWeight": "bold",
    "color": {
      "expr": "textColor"
    },
    "subtitleFontSize": {
      "expr": "length(subtitle) > 0 ? subtitleFontSize : 0"
    },
    "subtitleColor": {
      "expr": "subtitleColor"
    }
  },
  "data": {
    "name": "dataset"
  },
  "transform": [
    {
      "calculate": "isValid(datum[''Category'']) ? datum[''Category''] + '''' : ''''",
      "as": "catText"
    },
    {
      "calculate": "isValid(datum[''Current'']) ? max(0, datum[''Current'']) : 0",
      "as": "valCurrent"
    },
    {
      "calculate": "isValid(datum[''Total'']) ? max(0, datum[''Total'']) : 0",
      "as": "valTotal"
    },
    {
      "calculate": "isValid(datum[''Current'']) && isValid(datum[''Total'']) && datum[''Total''] != 0 ? datum[''Current''] / datum[''Total''] : null",
      "as": "share"
    },
    {
      "calculate": "max(datum.valCurrent, datum.valTotal)",
      "as": "valMax"
    },
    {
      "joinaggregate": [
        {
          "op": "max",
          "field": "valMax",
          "as": "scaleMax"
        },
        {
          "op": "max",
          "field": "share",
          "as": "shareMaxData"
        }
      ]
    },
    {
      "calculate": "shareAxisMax > 0 ? shareAxisMax : (datum.shareMaxData > 0 ? datum.shareMaxData : 1)",
      "as": "shareMax"
    },
    {
      "calculate": "isValid(datum[''Current'']) ? format(datum[''Current''] / valueDivisor, valueFormat) + valueSuffix : ''''",
      "as": "labelCurrent"
    },
    {
      "calculate": "isValid(datum[''Total'']) ? format(datum[''Total''] / valueDivisor, valueFormat) + valueSuffix : ''''",
      "as": "labelTotal"
    },
    {
      "calculate": "isValid(datum.share) ? format(datum.share, shareFormat) : ''''",
      "as": "labelShare"
    },
    {
      "calculate": "length(datum.labelShare)",
      "as": "labelShareChars"
    },
    {
      "joinaggregate": [
        {
          "op": "max",
          "field": "labelShareChars",
          "as": "labelShareCharsMax"
        }
      ]
    },
    {
      "calculate": "sqrt(lollipopHeadSize / PI) + labelGap + 4 + datum.labelShareCharsMax * shareFontSize * labelCharWidth",
      "as": "shareLabelSpace"
    },
    {
      "calculate": "max(0.1, 1 - datum.shareLabelSpace / max(width, 1) - lollipopLength - lollipopGap)",
      "as": "barAreaEnd"
    },
    {
      "calculate": "datum.scaleMax > 0 ? datum.valTotal / datum.scaleMax * datum.barAreaEnd : 0",
      "as": "xTotal"
    },
    {
      "calculate": "datum.scaleMax > 0 ? datum.valCurrent / datum.scaleMax * datum.barAreaEnd : 0",
      "as": "xCurrent"
    },
    {
      "calculate": "datum.barAreaEnd + lollipopGap",
      "as": "xStemStart"
    },
    {
      "calculate": "datum.xStemStart + (isValid(datum.share) ? clamp(datum.share / datum.shareMax, 0, 1) : 0) * lollipopLength",
      "as": "xStemEnd"
    },
    {
      "calculate": "length(datum.labelTotal) * labelFontSize * labelCharWidth + 2 * labelGap",
      "as": "labelTotalPx"
    },
    {
      "calculate": "length(datum.labelCurrent) * labelFontSize * labelCharWidth + 2 * labelGap",
      "as": "labelCurrentPx"
    },
    {
      "calculate": "datum.xTotal * width >= datum.labelTotalPx",
      "as": "labelTotalInside"
    },
    {
      "calculate": "datum.labelTotalInside || (datum.xStemStart - datum.xTotal) * width >= datum.labelTotalPx",
      "as": "labelTotalShown"
    },
    {
      "calculate": "datum.xCurrent * width >= datum.labelCurrentPx",
      "as": "labelCurrentInside"
    },
    {
      "calculate": "datum.labelCurrentInside || (datum.xStemStart - datum.xCurrent) * width >= datum.labelCurrentPx",
      "as": "labelCurrentShown"
    },
    {
      "calculate": "isValid(datum[''Current'']) ? format(datum[''Current''], tooltipValueFormat) : ''''",
      "as": "tipCurrent"
    },
    {
      "calculate": "isValid(datum[''Total'']) ? format(datum[''Total''], tooltipValueFormat) : ''''",
      "as": "tipTotal"
    },
    {
      "calculate": "(sortDescending ? -1 : 1) * (sortBy == ''total'' ? datum.valTotal : sortBy == ''share'' ? (isValid(datum.share) ? datum.share : 0) : datum.valCurrent)",
      "as": "sortKey"
    },
    {
      "calculate": "floor(length(datum.catText) / 2)",
      "as": "catMid"
    },
    {
      "calculate": "lastindexof(datum.catText, '' '', datum.catMid)",
      "as": "catSpaceBefore"
    },
    {
      "calculate": "indexof(datum.catText, '' '', datum.catMid)",
      "as": "catSpaceAfter"
    },
    {
      "calculate": "datum.catSpaceBefore < 0 ? datum.catSpaceAfter : datum.catSpaceAfter < 0 ? datum.catSpaceBefore : (datum.catMid - datum.catSpaceBefore <= datum.catSpaceAfter - datum.catMid ? datum.catSpaceBefore : datum.catSpaceAfter)",
      "as": "catCut"
    },
    {
      "calculate": "length(datum.catText) > categoryWrapChars && datum.catCut > 0 ? [substring(datum.catText, 0, datum.catCut), substring(datum.catText, datum.catCut + 1)] : datum.catText",
      "as": "catLines"
    }
  ],
  "encoding": {
    "y": {
      "field": "Category",
      "type": "nominal",
      "sort": {
        "field": "sortKey",
        "op": "min",
        "order": "ascending"
      },
      "scale": {
        "paddingInner": 0,
        "paddingOuter": 0
      },
      "axis": null
    },
    "tooltip": [
      {
        "field": "Category",
        "type": "nominal",
        "title": "Category"
      },
      {
        "field": "tipCurrent",
        "type": "nominal",
        "title": "Current"
      },
      {
        "field": "tipTotal",
        "type": "nominal",
        "title": "Total"
      },
      {
        "field": "labelShare",
        "type": "nominal",
        "title": "Share of Total"
      }
    ]
  },
  "layer": [
    {
      "transform": [
        {
          "filter": "datum.xTotal > 0"
        }
      ],
      "mark": {
        "type": "bar",
        "fill": {
          "expr": "totalBarColor"
        },
        "stroke": {
          "expr": "totalBarStroke"
        },
        "strokeWidth": {
          "expr": "barStrokeWidth"
        },
        "size": {
          "expr": "bandwidth(''y'') * totalBarHeight"
        },
        "yOffset": {
          "expr": "bandwidth(''y'') * totalBarOffset"
        }
      },
      "encoding": {
        "x": {
          "field": "xTotal",
          "type": "quantitative",
          "scale": {
            "domain": [
              0,
              1
            ],
            "nice": false,
            "zero": true
          },
          "axis": null
        },
        "x2": {
          "datum": 0
        }
      }
    },
    {
      "transform": [
        {
          "filter": "datum.xCurrent > 0"
        }
      ],
      "mark": {
        "type": "bar",
        "fill": {
          "expr": "currentBarColor"
        },
        "stroke": {
          "expr": "currentBarStroke"
        },
        "strokeWidth": {
          "expr": "barStrokeWidth"
        },
        "size": {
          "expr": "bandwidth(''y'') * currentBarHeight"
        },
        "yOffset": {
          "expr": "bandwidth(''y'') * currentBarOffset"
        }
      },
      "encoding": {
        "x": {
          "field": "xCurrent",
          "type": "quantitative",
          "scale": {
            "domain": [
              0,
              1
            ],
            "nice": false,
            "zero": true
          },
          "axis": null
        },
        "x2": {
          "datum": 0
        }
      }
    },
    {
      "transform": [
        {
          "filter": "isValid(datum.share)"
        }
      ],
      "mark": {
        "type": "rule",
        "stroke": {
          "expr": "lollipopStemColor"
        },
        "strokeWidth": {
          "expr": "lollipopStemWidth"
        },
        "yOffset": {
          "expr": "bandwidth(''y'') * lollipopOffset"
        }
      },
      "encoding": {
        "x": {
          "field": "xStemStart",
          "type": "quantitative",
          "scale": {
            "domain": [
              0,
              1
            ],
            "nice": false,
            "zero": true
          },
          "axis": null
        },
        "x2": {
          "field": "xStemEnd"
        }
      }
    },
    {
      "transform": [
        {
          "filter": "isValid(datum.share)"
        }
      ],
      "mark": {
        "type": "point",
        "shape": "circle",
        "filled": true,
        "opacity": 1,
        "fill": {
          "expr": "lollipopHeadColor"
        },
        "stroke": {
          "expr": "lollipopHeadStroke"
        },
        "strokeWidth": {
          "expr": "lollipopHeadStrokeWidth"
        },
        "size": {
          "expr": "lollipopHeadSize"
        },
        "yOffset": {
          "expr": "bandwidth(''y'') * lollipopOffset"
        }
      },
      "encoding": {
        "x": {
          "field": "xStemEnd",
          "type": "quantitative",
          "scale": {
            "domain": [
              0,
              1
            ],
            "nice": false,
            "zero": true
          },
          "axis": null
        }
      }
    },
    {
      "mark": {
        "type": "text",
        "align": "right",
        "baseline": "middle",
        "dx": {
          "expr": "-categoryGap"
        },
        "fill": {
          "expr": "textColor"
        },
        "fontSize": {
          "expr": "categoryFontSize"
        },
        "lineHeight": {
          "expr": "categoryFontSize * 1.2"
        },
        "limit": {
          "expr": "categoryLabelLimit"
        }
      },
      "encoding": {
        "x": {
          "datum": 0,
          "type": "quantitative",
          "scale": {
            "domain": [
              0,
              1
            ],
            "nice": false,
            "zero": true
          },
          "axis": null
        },
        "text": {
          "field": "catLines"
        }
      }
    },
    {
      "transform": [
        {
          "filter": "datum.labelTotalShown"
        }
      ],
      "mark": {
        "type": "text",
        "baseline": "middle",
        "align": {
          "expr": "datum.labelTotalInside ? ''right'' : ''left''"
        },
        "dx": {
          "expr": "datum.labelTotalInside ? -labelGap : labelGap"
        },
        "yOffset": {
          "expr": "bandwidth(''y'') * (totalBarOffset - totalBarHeight / 2 + currentBarOffset - currentBarHeight / 2) / 2"
        },
        "fill": {
          "expr": "textColor"
        },
        "fontSize": {
          "expr": "labelFontSize"
        }
      },
      "encoding": {
        "x": {
          "field": "xTotal",
          "type": "quantitative",
          "scale": {
            "domain": [
              0,
              1
            ],
            "nice": false,
            "zero": true
          },
          "axis": null
        },
        "text": {
          "field": "labelTotal"
        }
      }
    },
    {
      "transform": [
        {
          "filter": "datum.labelCurrentShown"
        }
      ],
      "mark": {
        "type": "text",
        "baseline": "middle",
        "align": {
          "expr": "datum.labelCurrentInside ? ''right'' : ''left''"
        },
        "dx": {
          "expr": "datum.labelCurrentInside ? -labelGap : labelGap"
        },
        "fill": {
          "expr": "datum.labelCurrentInside ? currentLabelColor : textColor"
        },
        "yOffset": {
          "expr": "!datum.labelCurrentInside && datum.xCurrent < datum.xTotal ? max(bandwidth(''y'') * currentBarOffset, bandwidth(''y'') * (totalBarOffset + totalBarHeight / 2) + barStrokeWidth / 2 + 1 + 0.42 * labelFontSize) : bandwidth(''y'') * currentBarOffset"
        },
        "fontSize": {
          "expr": "labelFontSize"
        }
      },
      "encoding": {
        "x": {
          "field": "xCurrent",
          "type": "quantitative",
          "scale": {
            "domain": [
              0,
              1
            ],
            "nice": false,
            "zero": true
          },
          "axis": null
        },
        "text": {
          "field": "labelCurrent"
        }
      }
    },
    {
      "transform": [
        {
          "filter": "isValid(datum.share)"
        }
      ],
      "mark": {
        "type": "text",
        "align": "left",
        "baseline": "middle",
        "dx": {
          "expr": "sqrt(lollipopHeadSize / PI) + labelGap + 2"
        },
        "yOffset": {
          "expr": "bandwidth(''y'') * lollipopOffset"
        },
        "fill": {
          "expr": "textColor"
        },
        "fontSize": {
          "expr": "shareFontSize"
        }
      },
      "encoding": {
        "x": {
          "field": "xStemEnd",
          "type": "quantitative",
          "scale": {
            "domain": [
              0,
              1
            ],
            "nice": false,
            "zero": true
          },
          "axis": null
        },
        "text": {
          "field": "labelShare"
        }
      }
    }
  ]
}'
